export type RuntimeBrandName = string;

/*
 * Los iconos tecnológicos se resuelven desde assets SVG locales. Los datos
 * embebidos se conservan como fallback offline para runtimes conocidos.
 */
const runtimeBrandSources: Record<string, string> = {
  Java: "data:image/svg+xml;base64,",
  "Node.js": "data:image/svg+xml;base64,",
  Docker: "data:image/svg+xml;base64,",
  Python: "data:image/svg+xml;base64,",
  PHP: "data:image/svg+xml;base64,",
  Composer: "data:image/svg+xml;base64,",
  ".NET": "data:image/svg+xml;base64,",
  Go: "data:image/svg+xml;base64,",
  Rust: "data:image/svg+xml;base64,",
  Ruby: "data:image/svg+xml;base64,",
  Elixir: "data:image/svg+xml;base64,",
};

const runtimeBrandFallbacks: Record<string, string> = {
  Java: "JV",
  "Node.js": "JS",
  Docker: "DK",
  Python: "PY",
  PHP: "PH",
  Composer: "CO",
  ".NET": "NT",
  Go: "GO",
  Rust: "RS",
  Cargo: "CG",
  Ruby: "RB",
  Elixir: "EX",
  Mix: "MX",
  JVM: "JV"
};

export function RuntimeBrandIcon({
  name,
  size = 30
}: IconProps & { name: RuntimeBrandName }) {
  const source = technologyIconUrl(name) ?? runtimeBrandSources[name];
  const fallback = runtimeBrandFallbacks[name] ?? (name.replace(/[^a-z0-9]/gi, "").slice(0, 2).toUpperCase() || "RT");
  return (
    <span className="runtime-brand" style={{ width: size, height: size }}>
      <span className="runtime-brand-fallback" aria-hidden="true">
        {fallback}
      </span>
      {source && (
        <img
          className="runtime-brand-icon"
          src={source}
          width={size}
          height={size}
          alt=""
          aria-hidden="true"
          draggable={false}
          onLoad={(event) => event.currentTarget.parentElement?.classList.add("is-loaded")}
          onError={(event) => event.currentTarget.remove()}
        />
      )}
    </span>
  );
}

